using System;
using Framework.Grid;
using Framework.AI.Perception;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 認識情報、視線判定、グリッド視覚センサーを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class AgentPerceptionTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべての認識システムのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestStimulus();
                TestLineOfSight();
                TestObstacles();
                TestRange();
                TestFieldOfView();
                TestObservation();
                TestConfiguration();
                TestInvalidInput();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【AgentPerception テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0 && passedCount == 40
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストを確認してください。"),
                this);
        }

        /// <summary>
        /// 遮蔽物のないテスト用グリッドを生成する。
        /// </summary>
        /// <returns>9×9のグリッド。trueは遮蔽物</returns>
        private GridMap<bool> CreateMap()
        {
            return new GridMap<bool>(
                9,
                9,
                position => false);
        }

        /// <summary>
        /// テスト用視覚センサーを生成する。
        /// </summary>
        /// <param name="map">判定対象のグリッド</param>
        /// <param name="range">認識距離。単位はセル</param>
        /// <param name="fieldOfView">視野角。単位は度</param>
        /// <returns>生成した視覚センサー</returns>
        private GridVisionSensor<bool> CreateSensor(
            GridMap<bool> map,
            float range = 5f,
            float fieldOfView = 360f)
        {
            return new GridVisionSensor<bool>(
                map,
                position => map.GetCell(position),
                range,
                fieldOfView);
        }

        /// <summary>
        /// 認識情報の保持と既定値を検証する。
        /// </summary>
        private void TestStimulus()
        {
            Guid sourceId = Guid.NewGuid();

            var position = new Vector2Int(3, 4);

            var stimulus =
                new PerceptionStimulus<Vector2Int>(
                    sourceId,
                    PerceptionType.Sight,
                    position,
                    0.8f,
                    12.5d);

            bool sourcePassed =
                stimulus.SourceId == sourceId &&
                stimulus.Type == PerceptionType.Sight;
            Debug.Assert(sourcePassed, "認識対象と認識手段", this);
            Check(sourcePassed, "認識対象と認識手段");

            bool positionPassed =
                stimulus.Position == position;
            Debug.Assert(positionPassed, "認識位置の保持", this);
            Check(positionPassed, "認識位置の保持");

            bool dataPassed =
                stimulus.Confidence == 0.8f &&
                stimulus.Timestamp == 12.5d &&
                stimulus.IsValid;
            Debug.Assert(dataPassed, "信頼度と認識時刻", this);
            Check(dataPassed, "信頼度と認識時刻");

            position = new Vector2Int(5, 6);

            bool snapshotPassed =
                stimulus.Position == new Vector2Int(3, 4);
            Debug.Assert(snapshotPassed, "認識時点の位置保持", this);
            Check(snapshotPassed, "認識時点の位置保持");

            var empty =
                default(PerceptionStimulus<Vector2Int>);

            bool defaultPassed = !empty.IsValid;
            Debug.Assert(defaultPassed, "既定認識情報の無効状態", this);
            Check(defaultPassed, "既定認識情報の無効状態");
        }

        /// <summary>
        /// 基本的な視線判定を検証する。
        /// </summary>
        private void TestLineOfSight()
        {
            var map = CreateMap();

            Func<Vector2Int, bool> blocksSight =
                position => map.GetCell(position);

            var origin = new Vector2Int(1, 1);

            bool horizontalPassed =
                GridLineOfSight.HasLineOfSight(
                    map, origin,
                    new Vector2Int(7, 1),
                    blocksSight);
            Debug.Assert(horizontalPassed, "水平方向の視線", this);
            Check(horizontalPassed, "水平方向の視線");

            bool verticalPassed =
                GridLineOfSight.HasLineOfSight(
                    map, origin,
                    new Vector2Int(1, 7),
                    blocksSight);
            Debug.Assert(verticalPassed, "垂直方向の視線", this);
            Check(verticalPassed, "垂直方向の視線");

            bool diagonalPassed =
                GridLineOfSight.HasLineOfSight(
                    map, origin,
                    new Vector2Int(7, 7),
                    blocksSight);
            Debug.Assert(diagonalPassed, "斜め方向の視線", this);
            Check(diagonalPassed, "斜め方向の視線");

            bool reversePassed =
                GridLineOfSight.HasLineOfSight(
                    map,
                    new Vector2Int(7, 5),
                    origin,
                    blocksSight);
            Debug.Assert(reversePassed, "逆方向の視線", this);
            Check(reversePassed, "逆方向の視線");

            bool samePassed =
                GridLineOfSight.HasLineOfSight(
                    map, origin, origin, blocksSight);
            Debug.Assert(samePassed, "同一セルの視線", this);
            Check(samePassed, "同一セルの視線");

            bool outsidePassed =
                !GridLineOfSight.HasLineOfSight(
                    map, origin,
                    new Vector2Int(9, 1),
                    blocksSight) &&
                !GridLineOfSight.HasLineOfSight(
                    map,
                    new Vector2Int(-1, 1),
                    origin,
                    blocksSight);
            Debug.Assert(outsidePassed, "範囲外の視線拒否", this);
            Check(outsidePassed, "範囲外の視線拒否");
        }

        /// <summary>
        /// 遮蔽物とセルの角による遮蔽を検証する。
        /// </summary>
        private void TestObstacles()
        {
            var map = CreateMap();

            Func<Vector2Int, bool> blocksSight =
                position => map.GetCell(position);

            var origin = new Vector2Int(1, 1);
            var target = new Vector2Int(5, 1);
            var wall = new Vector2Int(3, 1);

            map.SetCell(wall, true);

            bool wallPassed =
                !GridLineOfSight.HasLineOfSight(
                    map, origin, target, blocksSight);
            Debug.Assert(wallPassed, "壁による視線遮断", this);
            Check(wallPassed, "壁による視線遮断");

            map.SetCell(wall, false);

            bool removedPassed =
                GridLineOfSight.HasLineOfSight(
                    map, origin, target, blocksSight);
            Debug.Assert(removedPassed, "壁除去後の視線回復", this);
            Check(removedPassed, "壁除去後の視線回復");

            map.SetCell(target, true);

            bool targetPassed =
                !GridLineOfSight.HasLineOfSight(
                    map, origin, target, blocksSight);
            Debug.Assert(targetPassed, "終点セルの遮蔽", this);
            Check(targetPassed, "終点セルの遮蔽");

            map.SetCell(target, false);
            map.SetCell(origin, true);

            bool originPassed =
                GridLineOfSight.HasLineOfSight(
                    map, origin, target, blocksSight);
            Debug.Assert(originPassed, "始点セルの遮蔽除外", this);
            Check(originPassed, "始点セルの遮蔽除外");

            map.SetCell(origin, false);

            var diagonalTarget = new Vector2Int(3, 3);

            map.SetCell(new Vector2Int(2, 1), true);

            bool cornerPassed =
                !GridLineOfSight.HasLineOfSight(
                    map, origin,
                    diagonalTarget,
                    blocksSight);
            Debug.Assert(cornerPassed, "斜め方向の角による遮蔽", this);
            Check(cornerPassed, "斜め方向の角による遮蔽");

            map.SetCell(new Vector2Int(2, 1), false);
            map.SetCell(new Vector2Int(1, 2), true);

            bool otherCornerPassed =
                !GridLineOfSight.HasLineOfSight(
                    map, origin,
                    diagonalTarget,
                    blocksSight) &&
                !GridLineOfSight.HasLineOfSight(
                    map, diagonalTarget,
                    origin,
                    blocksSight);
            Debug.Assert(otherCornerPassed, "反対側の角と逆方向の遮蔽", this);
            Check(otherCornerPassed, "反対側の角と逆方向の遮蔽");
        }

        /// <summary>
        /// 認識距離と距離の境界条件を検証する。
        /// </summary>
        private void TestRange()
        {
            var map = CreateMap();

            var sensor = CreateSensor(map, 5f);

            var origin = new Vector2Int(1, 1);

            bool insidePassed =
                sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(4, 1));
            Debug.Assert(insidePassed, "認識距離内の対象", this);
            Check(insidePassed, "認識距離内の対象");

            bool boundaryPassed =
                sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(6, 1));
            Debug.Assert(boundaryPassed, "認識距離の境界", this);
            Check(boundaryPassed, "認識距離の境界");

            bool outsidePassed =
                !sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(7, 1));
            Debug.Assert(outsidePassed, "認識距離外の対象", this);
            Check(outsidePassed, "認識距離外の対象");

            bool diagonalPassed =
                sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(4, 5)) &&
                !sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(5, 5));
            Debug.Assert(diagonalPassed, "ユークリッド距離による判定", this);
            Check(diagonalPassed, "ユークリッド距離による判定");

            sensor.Configure(0f, 360f);

            bool zeroPassed =
                sensor.CanSee(
                    origin, Vector2Int.zero, origin) &&
                !sensor.CanSee(
                    origin, Vector2Int.right,
                    origin + Vector2Int.right);
            Debug.Assert(zeroPassed, "認識距離0の境界条件", this);
            Check(zeroPassed, "認識距離0の境界条件");
        }

        /// <summary>
        /// 視野角と観測方向を検証する。
        /// </summary>
        private void TestFieldOfView()
        {
            var map = CreateMap();

            var sensor = CreateSensor(map, 5f, 90f);

            var origin = new Vector2Int(4, 4);

            bool frontPassed =
                sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(6, 4));
            Debug.Assert(frontPassed, "正面方向の認識", this);
            Check(frontPassed, "正面方向の認識");

            bool behindPassed =
                !sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(2, 4));
            Debug.Assert(behindPassed, "背後の認識抑止", this);
            Check(behindPassed, "背後の認識抑止");

            bool sidePassed =
                !sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(4, 6));
            Debug.Assert(sidePassed, "視野角外の認識抑止", this);
            Check(sidePassed, "視野角外の認識抑止");

            bool boundaryPassed =
                sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(6, 6));
            Debug.Assert(boundaryPassed, "視野角の境界", this);
            Check(boundaryPassed, "視野角の境界");

            bool zeroDirectionPassed =
                !sensor.CanSee(
                    origin, Vector2Int.zero,
                    new Vector2Int(6, 4));
            Debug.Assert(zeroDirectionPassed, "向き未指定時の認識抑止", this);
            Check(zeroDirectionPassed, "向き未指定時の認識抑止");

            sensor.Configure(5f, 360f);

            bool fullPassed =
                sensor.CanSee(
                    origin, Vector2Int.right,
                    new Vector2Int(2, 4)) &&
                sensor.CanSee(
                    origin, Vector2Int.zero,
                    new Vector2Int(4, 6));
            Debug.Assert(fullPassed, "全方向の認識", this);
            Check(fullPassed, "全方向の認識");
        }

        /// <summary>
        /// 視覚認識による刺激情報の生成を検証する。
        /// </summary>
        private void TestObservation()
        {
            var map = CreateMap();

            var sensor = CreateSensor(map);

            Guid sourceId = Guid.NewGuid();

            var origin = new Vector2Int(1, 1);
            var target = new Vector2Int(4, 1);

            bool observed = sensor.TryObserve(
                sourceId,
                origin,
                Vector2Int.right,
                target,
                10d,
                out PerceptionStimulus<Vector2Int> stimulus);

            bool successPassed =
                observed && stimulus.IsValid;
            Debug.Assert(successPassed, "視覚認識の成功", this);
            Check(successPassed, "視覚認識の成功");

            bool dataPassed =
                stimulus.SourceId == sourceId &&
                stimulus.Type == PerceptionType.Sight &&
                stimulus.Position == target &&
                stimulus.Confidence == 1f &&
                stimulus.Timestamp == 10d;
            Debug.Assert(dataPassed, "視覚認識情報の内容", this);
            Check(dataPassed, "視覚認識情報の内容");

            map.SetCell(new Vector2Int(2, 1), true);

            bool blockedPassed =
                !sensor.TryObserve(
                    sourceId,
                    origin,
                    Vector2Int.right,
                    target,
                    11d,
                    out PerceptionStimulus<Vector2Int> blocked);
            Debug.Assert(blockedPassed, "遮蔽物による認識失敗", this);
            Check(blockedPassed, "遮蔽物による認識失敗");

            bool defaultPassed =
                !blocked.IsValid &&
                blocked.SourceId == Guid.Empty;
            Debug.Assert(defaultPassed, "認識失敗時の既定値", this);
            Check(defaultPassed, "認識失敗時の既定値");
        }

        /// <summary>
        /// 設定変更と不要な遮蔽判定の省略を検証する。
        /// </summary>
        private void TestConfiguration()
        {
            var map = CreateMap();

            // 遮蔽判定処理の呼び出し件数。
            int queryCount = 0;

            var sensor = new GridVisionSensor<bool>(
                map,
                position =>
                {
                    queryCount++;

                    return map.GetCell(position);
                },
                2f,
                90f);

            var origin = new Vector2Int(4, 4);

            sensor.CanSee(
                origin,
                Vector2Int.right,
                new Vector2Int(8, 4));

            bool rangeSkipPassed = queryCount == 0;
            Debug.Assert(rangeSkipPassed, "距離判定による遮蔽処理省略", this);
            Check(rangeSkipPassed, "距離判定による遮蔽処理省略");

            sensor.CanSee(
                origin,
                Vector2Int.right,
                new Vector2Int(3, 4));

            bool angleSkipPassed = queryCount == 0;
            Debug.Assert(angleSkipPassed, "視野角による遮蔽処理省略", this);
            Check(angleSkipPassed, "視野角による遮蔽処理省略");

            sensor.Configure(4f, 360f);

            bool configurePassed =
                sensor.Range == 4f &&
                sensor.FieldOfView == 360f &&
                sensor.CanSee(
                    origin,
                    Vector2Int.right,
                    new Vector2Int(1, 4)) &&
                queryCount > 0;
            Debug.Assert(configurePassed, "設定変更の即時反映", this);
            Check(configurePassed, "設定変更の即時反映");

            bool rejected =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    sensor.Configure(7f, 361f);
                });

            bool preservePassed =
                rejected &&
                sensor.Range == 4f &&
                sensor.FieldOfView == 360f;
            Debug.Assert(preservePassed, "不正設定時の既存設定維持", this);
            Check(preservePassed, "不正設定時の既存設定維持");
        }

        /// <summary>
        /// 不正な引数が拒否されることを検証する。
        /// </summary>
        private void TestInvalidInput()
        {
            var map = CreateMap();

            bool mapPassed =
                Throws<ArgumentNullException>(() =>
                {
                    new GridVisionSensor<bool>(
                        null,
                        position => false);
                });
            Debug.Assert(mapPassed, "nullグリッドの拒否", this);
            Check(mapPassed, "nullグリッドの拒否");

            bool predicatePassed =
                Throws<ArgumentNullException>(() =>
                {
                    new GridVisionSensor<bool>(
                        map, null);
                });
            Debug.Assert(predicatePassed, "null遮蔽判定の拒否", this);
            Check(predicatePassed, "null遮蔽判定の拒否");

            bool rangePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new GridVisionSensor<bool>(
                        map,
                        position => false,
                        float.NaN);
                });
            Debug.Assert(rangePassed, "不正認識距離の拒否", this);
            Check(rangePassed, "不正認識距離の拒否");

            bool stimulusPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new PerceptionStimulus<Vector2Int>(
                        Guid.Empty,
                        PerceptionType.Sight,
                        Vector2Int.zero,
                        1.1f,
                        0d);
                });
            Debug.Assert(stimulusPassed, "不正信頼度の拒否", this);
            Check(stimulusPassed, "不正信頼度の拒否");
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、結果を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
